/*
 * Service worker.
 *
 * Scope of responsibility, from docs/08-OFFLINE-SYNC.md section 48:
 *
 *     The service worker caches the application shell and network responses.
 *     IndexedDB holds application data.
 *     The service worker is never the financial database.
 *
 * Nothing in this file reads, writes, or reasons about a transaction, a split, or a
 * balance. If a change here seems to require that, the change belongs in src/offline.
 *
 * Written by hand rather than generated by Workbox: the routing table below is about
 * forty lines, and a generated worker would hide the one rule that actually matters
 * (`/api/**` is never cached) behind a configuration file. It is also plain ES5-compatible
 * script so it can be evaluated in a test sandbox — see tests/offline/service-worker.test.ts.
 *
 * This file is excluded from ESLint and Prettier (see eslint.config.mjs and
 * .prettierignore) because it runs in a worker global scope those tools do not model.
 */

"use strict";

/**
 * Bump this to evict every cache on the next activation.
 *
 * Required whenever the shape of what is cached changes, because `activate` deletes any
 * cache whose name is not in the current set.
 *
 * v1 -> v2: the app moved from system fonts to three self-hosted faces
 * (`src/app/fonts.ts`). Existing clients have a shell cached from before the font files
 * existed, so without a bump their first offline load would still fall back to system
 * sans — the exact failure the precache is supposed to prevent.
 */
var VERSION = "v2";

var CACHE_PREFIX = "expense-tracker-";

var CACHE_NAMES = {
  /** Precached fallbacks and icons. No user data. */
  shell: CACHE_PREFIX + "shell-" + VERSION,
  /** Content-hashed build output. Immutable, so safe to serve cache-first. No user data. */
  static: CACHE_PREFIX + "static-" + VERSION,
  /** Rendered HTML for authenticated pages. CONTAINS USER DATA — cleared on sign-out. */
  pages: CACHE_PREFIX + "pages-" + VERSION
};

var OFFLINE_URL = "/offline";

/**
 * Fetched during install so the app can start with no connection at all.
 *
 * Deliberately short. Every entry costs storage on a device that may also be holding
 * unsynced expenses, and section 47 warns against treating IndexedDB quota as unlimited.
 */
var PRECACHE_URLS = [
  OFFLINE_URL,
  "/manifest.webmanifest",
  "/icons/icon.svg",
  "/icons/icon-192.png",
  "/icons/icon-512.png",
  "/icons/apple-touch-icon.png"
];

/** Kept in step with SERVICE_WORKER_MESSAGES in src/offline/pwa/service-worker.ts. */
var MESSAGES = {
  skipWaiting: "SKIP_WAITING",
  clearPrivateCaches: "CLEAR_PRIVATE_CACHES",
  privateCachesCleared: "PRIVATE_CACHES_CLEARED"
};

/* ------------------------------------------------------------------------- *
 * Routing
 * ------------------------------------------------------------------------- */

/**
 * True for a request the browser is making to render a new document.
 *
 * Three checks because no single one is universally available: `mode` is the modern
 * signal, `destination` covers older WebKit, and the Accept header is the last resort.
 */
function isNavigationRequest(request) {
  if (!request) return false;
  if (request.mode === "navigate") return true;
  if (request.destination === "document") return true;

  var accept = request.headers && request.headers.get ? request.headers.get("accept") : null;
  return typeof accept === "string" && accept.indexOf("text/html") !== -1;
}

/** Content-hashed build output: the URL changes when the bytes change. */
function isImmutableAsset(pathname) {
  return pathname.indexOf("/_next/static/") === 0;
}

/** Small public files that rarely change but must survive offline. */
function isPublicAsset(pathname) {
  return (
    pathname.indexOf("/icons/") === 0 ||
    pathname === "/manifest.webmanifest" ||
    pathname === "/favicon.ico"
  );
}

/**
 * Picks a caching strategy for one request.
 *
 * Pure, and exported through `self.__swInternals`, because this table is the security
 * boundary of the whole file and needs to be tested directly rather than inferred from
 * behaviour.
 *
 * Returns one of:
 *   "network-only"             not intercepted at all
 *   "navigation"               network first, cached HTML as fallback, then /offline
 *   "cache-first"              served from cache when present
 *   "stale-while-revalidate"   cached copy now, refreshed in the background
 */
function decideStrategy(request, scopeOrigin) {
  if (!request) return "network-only";

  // Only GET is ever cacheable. A POST to /api/sync/push must reach the server or fail
  // loudly; a cached "success" would tell the client an expense had synced when it never
  // left the device.
  if (request.method !== "GET") return "network-only";

  var url;
  try {
    url = new URL(request.url);
  } catch (error) {
    return "network-only";
  }

  // Another origin's caching policy is not ours to decide.
  if (scopeOrigin && url.origin !== scopeOrigin) return "network-only";

  /*
   * Every API response is network-only, without exception.
   *
   * This is the rule the rest of the file exists to protect. A cached
   * /api/sync/pull would hand the client a stale financial snapshot it believes is
   * current; a cached /api/auth response would resurrect a signed-out session. The
   * authoritative data path is: server -> IndexedDB, never server -> Cache API.
   */
  if (url.pathname.indexOf("/api/") === 0) return "network-only";

  // App Router flight payloads for client-side navigation. Serving a stale one would
  // render a stale screen inside an otherwise fresh app; a failed one makes Next fall
  // back to a full navigation, which the navigation strategy below does handle.
  if (url.searchParams && url.searchParams.has("_rsc")) return "network-only";

  if (isImmutableAsset(url.pathname)) return "cache-first";

  // Optimised images are generated on demand and vary by device; caching them here would
  // duplicate what the HTTP cache already does well.
  if (url.pathname.indexOf("/_next/image") === 0) return "network-only";

  if (isPublicAsset(url.pathname)) return "stale-while-revalidate";

  if (isNavigationRequest(request)) return "navigation";

  return "network-only";
}

/**
 * Whether a navigation response may be stored.
 *
 * The redirect check is the important one. `fetch()` follows redirects, so an
 * unauthenticated request for /dashboard resolves to the /login document. Caching that
 * under the /dashboard key would serve the login page as the dashboard forever after.
 */
function isCacheableNavigationResponse(response) {
  if (!response) return false;
  if (response.status !== 200) return false;
  if (response.redirected) return false;
  if (response.type === "opaqueredirect" || response.type === "error") return false;

  var contentType = response.headers && response.headers.get ? response.headers.get("content-type") : null;
  return typeof contentType === "string" && contentType.indexOf("text/html") !== -1;
}

/* ------------------------------------------------------------------------- *
 * Strategies
 * ------------------------------------------------------------------------- */

var OFFLINE_FALLBACK_BODY =
  '<!doctype html><html lang="en"><head><meta charset="utf-8">' +
  '<meta name="viewport" content="width=device-width, initial-scale=1">' +
  "<title>Offline</title></head><body>" +
  "<h1>You are offline</h1>" +
  "<p>Anything you saved on this device is safe and will sync when you reconnect.</p>" +
  "</body></html>";

function offlineFallbackResponse() {
  return new Response(OFFLINE_FALLBACK_BODY, {
    status: 503,
    headers: { "content-type": "text/html; charset=utf-8" }
  });
}

function unavailableResponse() {
  return new Response("", { status: 504, statusText: "Offline" });
}

/**
 * Network first, cached HTML second, the offline page last.
 *
 * Network first — not cache first — because financial figures must be current whenever
 * they can be. A cache-first shell would show yesterday's balances to a user who is
 * online, which is worse than a slightly slower page.
 *
 * The cache lookup uses the exact URL. `ignoreSearch` would let a request for
 * /transactions?accountId=x be answered with the unfiltered /transactions document, so
 * the user would read a filtered heading over unfiltered figures. `ignoreVary` is set
 * because Next varies HTML responses on its router headers, which a plain navigation does
 * not send; only document responses are ever put in this cache, so there is nothing else
 * a match could return.
 */
function isOfflineUrl(request) {
  try {
    return new URL(request.url).pathname === OFFLINE_URL;
  } catch (error) {
    return false;
  }
}

function handleNavigation(request, waitUntil) {
  return fetch(request)
    .then(function (response) {
      if (isCacheableNavigationResponse(response)) {
        var copy = response.clone();
        waitUntil(
          caches.open(CACHE_NAMES.pages).then(function (cache) {
            return cache.put(request, copy);
          })
        );
      }
      return response;
    })
    .catch(function () {
      return caches.match(request, { ignoreVary: true }).then(function (cached) {
        if (cached) return cached;

        /*
         * The fallback is a *redirect*, not the offline document served under the
         * requested URL.
         *
         * Serving /offline's HTML in answer to /accounts/123 leaves the App Router with a
         * document describing one route and an address bar showing another. It hydrates
         * against the mismatch and throws a client-side exception, so the user gets
         * "Application error" instead of the friendly page — which is the exact opposite of
         * the intent in docs/08-OFFLINE-SYNC.md section 49. Redirecting means the browser
         * navigates to /offline properly and the content matches the URL.
         *
         * A request for /offline that got here must not redirect again, or a missing
         * precache would become an infinite loop.
         */
        if (isOfflineUrl(request)) return offlineFallbackResponse();

        return Response.redirect(new URL(OFFLINE_URL, self.location.origin).toString(), 302);
      });
    });
}

function handleCacheFirst(request, cacheName, waitUntil) {
  return caches.open(cacheName).then(function (cache) {
    return cache.match(request).then(function (cached) {
      if (cached) return cached;

      return fetch(request)
        .then(function (response) {
          if (response && response.status === 200) {
            var copy = response.clone();
            waitUntil(cache.put(request, copy));
          }
          return response;
        })
        .catch(function () {
          return unavailableResponse();
        });
    });
  });
}

function handleStaleWhileRevalidate(request, cacheName, waitUntil) {
  return caches.open(cacheName).then(function (cache) {
    return cache.match(request).then(function (cached) {
      var refresh = fetch(request)
        .then(function (response) {
          if (response && response.status === 200) {
            return cache.put(request, response.clone()).then(function () {
              return response;
            });
          }
          return response;
        })
        .catch(function () {
          return null;
        });

      if (cached) {
        // Revalidation must be kept alive explicitly: the worker may be terminated as
        // soon as the response is returned.
        waitUntil(refresh);
        return cached;
      }

      return refresh.then(function (response) {
        return response || unavailableResponse();
      });
    });
  });
}

function handleRequest(strategy, request, waitUntil) {
  if (strategy === "navigation") return handleNavigation(request, waitUntil);
  if (strategy === "cache-first") return handleCacheFirst(request, CACHE_NAMES.static, waitUntil);
  if (strategy === "stale-while-revalidate") {
    return handleStaleWhileRevalidate(request, CACHE_NAMES.shell, waitUntil);
  }
  return fetch(request);
}

/* ------------------------------------------------------------------------- *
 * Cache maintenance
 * ------------------------------------------------------------------------- */

/**
 * Fetches one URL and stores it, or gives up quietly.
 *
 * Written out rather than using `cache.add()` so the response can be inspected first.
 * `add()` stores whatever it receives, including the login document that a redirect would
 * resolve to — the same poisoning `isCacheableNavigationResponse` exists to prevent, but
 * on the install path.
 */
function precacheUrl(cache, url) {
  return fetch(new Request(url, { cache: "reload" }))
    .then(function (response) {
      if (!response || response.status !== 200 || response.redirected) return null;
      return cache.put(url, response);
    })
    .catch(function () {
      // One missing icon must not stop the worker installing.
      return null;
    });
}

function precacheShell() {
  return caches.open(CACHE_NAMES.shell).then(function (cache) {
    return Promise.all(
      PRECACHE_URLS.map(function (url) {
        return precacheUrl(cache, url);
      })
    );
  });
}

/**
 * Pulls the `/_next/static/...` references out of a precached document.
 *
 * A regular expression over HTML is normally a poor idea, but the target here is
 * unambiguous: build asset paths are absolute, hashed, and appear in `src`, `href` and the
 * inline flight payload alike. Parsing properly would need a DOM, which a worker does not
 * have.
 *
 * It is also used on the stylesheets this finds, to reach the font files — see
 * `precacheNestedStylesheetAssets`. The same pattern works on CSS because `(` and `)` are
 * excluded, so a `url(/_next/static/media/x.woff2)` reference yields just the path.
 */
function extractStaticAssetUrls(html) {
  var pattern = /\/_next\/static\/[^"'\\\s<>()]+/g;
  var urls = [];
  var match = pattern.exec(html);

  while (match !== null) {
    if (urls.indexOf(match[0]) === -1) urls.push(match[0]);
    match = pattern.exec(html);
  }

  return urls;
}

/**
 * Caches the scripts and stylesheets the offline page needs to run.
 *
 * Without this the fallback is a shell that cannot hydrate: fetching a document does not
 * fetch its subresources, so /offline was cached while every chunk it references was not.
 * Offline, those requests fail and React never starts — the page renders for an instant and
 * is then replaced by Next's client-side error screen.
 *
 * Only the offline page is warmed this way. Every other route's assets arrive through the
 * cache-first strategy as the user visits it, and precaching the whole build would put
 * megabytes on a device that also has to hold unsynced expenses (section 47).
 */
function precacheOfflineAssets() {
  return caches
    .open(CACHE_NAMES.shell)
    .then(function (cache) {
      return cache.match(OFFLINE_URL);
    })
    .then(function (response) {
      return response ? response.text() : null;
    })
    .then(function (html) {
      if (!html) return null;

      var urls = extractStaticAssetUrls(html);
      if (urls.length === 0) return null;

      return caches
        .open(CACHE_NAMES.static)
        .then(function (cache) {
          return Promise.all(
            urls.map(function (url) {
              return precacheUrl(cache, url);
            })
          );
        })
        .then(function () {
          // Second pass, because the font files are one level deeper than the document.
          return precacheNestedStylesheetAssets(urls);
        });
    })
    .catch(function () {
      return null;
    });
}

/**
 * Caches the assets referenced from *inside* a precached stylesheet — in practice, the
 * self-hosted font files.
 *
 * ## Why a second pass is needed
 *
 * `next/font` does not put the font files in the HTML. Verified against a real build: the
 * prerendered `/offline` document contains no `/_next/static/media/` reference at all, only
 * a link to `/_next/static/css/<hash>.css`, and that stylesheet holds the `@font-face`
 * rules with `url(/_next/static/media/<hash>.woff2)` inside them. (Next emits `<link
 * rel="preload" as="font">` only for fonts it can attribute to a specific route; a
 * CSS-variable font applied at the root layout is not one of those.)
 *
 * So extracting from the document alone gets the stylesheet and stops. The browser then
 * asks for the font files when it applies the CSS, which offline fails — the app renders
 * in system sans, every amount loses its tabular figures and every eyebrow label loses its
 * tracking. It looks broken at exactly the moment the user is least able to explain why.
 *
 * ## Cost
 *
 * Three faces at the weights in `src/app/fonts.ts` come to roughly 200 KB across ~19
 * files, because Google splits each weight by unicode-range. Every one is referenced by an
 * `@font-face` rule, so this is the minimum correct set rather than a choice: caching a
 * subset would leave some glyphs rendering in the fallback face. It is a real cost on a
 * device that also has to hold unsynced expenses (section 47), and the reason there is no
 * fourth face.
 *
 * Nothing here is font-specific, deliberately. It caches whatever a precached stylesheet
 * references, so adding a weight, dropping a face or switching to a background image needs
 * no change — there is no font list to keep in step with `src/app/fonts.ts`.
 */
function precacheNestedStylesheetAssets(urls) {
  var stylesheets = urls.filter(function (url) {
    return url.indexOf(".css") !== -1;
  });

  if (stylesheets.length === 0) return Promise.resolve(null);

  return caches.open(CACHE_NAMES.static).then(function (cache) {
    return Promise.all(
      stylesheets.map(function (url) {
        // Read it back out of the cache rather than fetching it again: it was stored a
        // moment ago, and a second network round trip on the install path is latency the
        // user is waiting on.
        return cache
          .match(url)
          .then(function (response) {
            return response ? response.text() : null;
          })
          .then(function (css) {
            if (!css) return null;

            var nested = extractStaticAssetUrls(css);
            if (nested.length === 0) return null;

            return Promise.all(
              nested.map(function (nestedUrl) {
                return precacheUrl(cache, nestedUrl);
              })
            );
          })
          .catch(function () {
            // A font that fails to precache costs the right typeface offline, not the app.
            return null;
          });
      })
    );
  });
}

function deleteObsoleteCaches() {
  var current = [CACHE_NAMES.shell, CACHE_NAMES.static, CACHE_NAMES.pages];

  return caches.keys().then(function (names) {
    return Promise.all(
      names.map(function (name) {
        // Only this application's caches. Deleting anything else on the origin would be
        // overreach.
        if (name.indexOf(CACHE_PREFIX) !== 0) return null;
        if (current.indexOf(name) !== -1) return null;
        return caches.delete(name);
      })
    );
  });
}

/**
 * Drops everything that could contain one user's financial data.
 *
 * Called on sign-out. The rendered HTML in the pages cache shows balances and
 * descriptions, so on a shared device it must not outlive the session. The shell and
 * static caches are kept: they hold only build output and icons, and re-fetching them
 * would leave the next user unable to start the app offline.
 */
function clearPrivateCaches() {
  return caches.delete(CACHE_NAMES.pages);
}

/* ------------------------------------------------------------------------- *
 * Lifecycle
 * ------------------------------------------------------------------------- */

/**
 * Note the absence of `skipWaiting()` here.
 *
 * Activating immediately would swap the shell underneath a user who is part-way through
 * entering an expense. The new worker waits, and the client offers a reload — see
 * `applyServiceWorkerUpdate()` in src/offline/pwa/service-worker.ts.
 */
self.addEventListener("install", function (event) {
  // Assets second, because they are read out of the document cached by the first step.
  event.waitUntil(
    precacheShell().then(function () {
      return precacheOfflineAssets();
    })
  );
});

self.addEventListener("activate", function (event) {
  event.waitUntil(
    deleteObsoleteCaches().then(function () {
      return self.clients.claim();
    })
  );
});

self.addEventListener("fetch", function (event) {
  var strategy = decideStrategy(event.request, self.location && self.location.origin);

  // Not calling respondWith leaves the request entirely to the browser. That is what
  // "network-only" means here: no interception, no cache lookup, no stale answer.
  if (strategy === "network-only") return;

  event.respondWith(
    handleRequest(strategy, event.request, function (promise) {
      event.waitUntil(promise);
    })
  );
});

self.addEventListener("message", function (event) {
  var data = event.data;
  var type = data && data.type;

  if (type === MESSAGES.skipWaiting) {
    self.skipWaiting();
    return;
  }

  if (type === MESSAGES.clearPrivateCaches) {
    event.waitUntil(
      clearPrivateCaches().then(function () {
        var port = event.ports && event.ports[0];
        if (port) port.postMessage({ type: MESSAGES.privateCachesCleared });
      })
    );
  }
});

/**
 * Test seam.
 *
 * tests/offline/service-worker.test.ts evaluates this file in a sandbox and asserts on
 * these functions, so the routing table is verified in the artefact that actually ships
 * rather than in a TypeScript copy of it that could drift.
 */
self.__swInternals = {
  VERSION: VERSION,
  CACHE_PREFIX: CACHE_PREFIX,
  CACHE_NAMES: CACHE_NAMES,
  PRECACHE_URLS: PRECACHE_URLS,
  MESSAGES: MESSAGES,
  OFFLINE_URL: OFFLINE_URL,
  decideStrategy: decideStrategy,
  isNavigationRequest: isNavigationRequest,
  isImmutableAsset: isImmutableAsset,
  isPublicAsset: isPublicAsset,
  isCacheableNavigationResponse: isCacheableNavigationResponse,
  isOfflineUrl: isOfflineUrl,
  extractStaticAssetUrls: extractStaticAssetUrls,
  handleRequest: handleRequest,
  handleNavigation: handleNavigation,
  precacheShell: precacheShell,
  precacheOfflineAssets: precacheOfflineAssets,
  precacheNestedStylesheetAssets: precacheNestedStylesheetAssets,
  deleteObsoleteCaches: deleteObsoleteCaches,
  clearPrivateCaches: clearPrivateCaches
};
